// Booking assistant: a small state machine (no AI API needed). One message in, one reply out.
const CLINIC = { name: 'Smile Dental Clinic', tz: 'America/Chicago', tzLabel: 'Central Time', days: 3, hours: [9, 10, 11, 13, 14, 15, 16] };
const SERVICES = [
  { label: 'Check-up & cleaning', minutes: 45, words: ['check', 'clean'] },
  { label: 'Teeth whitening', minutes: 60, words: ['whiten', 'white'] },
  { label: 'Emergency visit', minutes: 30, words: ['emergency', 'pain', 'urgent', 'hurt'] },
];

const chat = $('Chat Trigger').first().json;
const sessionId = chat.sessionId;
const text = String(chat.chatInput || '').trim();
const lower = text.toLowerCase();
const row = $('Load Session').all().map(i => i.json).find(r => r.sessionId === sessionId);
let s = row && row.state ? JSON.parse(row.state) : { step: 'start' };
const booked = new Set($('Load Booked Slots').all().map(i => i.json).filter(r => r.status === 'booked' && r.start_iso).map(r => r.start_iso));

const now = DateTime.now().setZone(CLINIC.tz);
function freeSlots() {
  // Up to 2 options per working day (first free morning + first free afternoon) for the next N working days
  const out = [];
  let day = now.startOf('day');
  let added = 0;
  while (added < CLINIC.days) {
    day = day.plus({ days: 1 });
    if (day.weekday > 5) continue;
    added++;
    const free = CLINIC.hours.map(h => day.set({ hour: h })).filter(t => !booked.has(t.toUTC().toISO()));
    const am = free.find(t => t.hour < 12), pm = free.find(t => t.hour >= 13);
    for (const t of [am, pm]) if (t) out.push({ iso: t.toUTC().toISO(), label: t.toFormat('ccc d LLL, h:mm a') });
  }
  return out;
}
const menu = () => 'What would you like to book?\n' + SERVICES.map((x, i) => `${i + 1}. ${x.label} (${x.minutes} min)`).join('\n') + '\n\nReply with a number.';
const offerSlots = () => {
  s.offered = freeSlots();
  if (!s.offered.length) { s.step = 'service'; return 'Sorry, we are fully booked for the next few days. Please call the clinic and we will fit you in.'; }
  s.step = 'slot';
  return `Next available times (${CLINIC.tzLabel}):\n` + s.offered.map((o, i) => `${i + 1}. ${o.label}`).join('\n') + '\n\nReply with the number that suits you.';
};

let reply = '';
let booking = null;
if (['restart', 'start over', 'menu'].includes(lower)) s = { step: 'start' };

switch (s.step) {
  case 'start':
    s.step = 'service';
    reply = `Hi! I'm the booking assistant for ${CLINIC.name}. ` + menu();
    break;
  case 'service': {
    const n = parseInt(lower, 10);
    const svc = SERVICES[n - 1] || SERVICES.find(x => x.words.some(w => lower.includes(w)));
    if (!svc) { reply = 'Sorry, I didn\'t catch that. ' + menu(); break; }
    s.service = svc.label;
    reply = `Great, ${svc.label}. ` + offerSlots();
    break;
  }
  case 'slot': {
    const n = parseInt(lower, 10);
    const pick = s.offered && s.offered[n - 1];
    if (!pick) { reply = `Please reply with a number from 1 to ${(s.offered || []).length}.`; break; }
    if (booked.has(pick.iso)) { reply = 'That time was just taken. ' + offerSlots(); break; }
    s.slot = pick;
    s.step = 'name';
    reply = `${pick.label} it is. What's your full name?`;
    break;
  }
  case 'name':
    if (text.length < 2) { reply = 'Could you type your full name?'; break; }
    s.name = text.toLowerCase().replace(/\b\w/g, c => c.toUpperCase()).replace(/\s+/g, ' ');
    s.step = 'phone';
    reply = `Thanks, ${s.name.split(' ')[0]}! What's the best phone number to reach you? Your reminder goes there.`;
    break;
  case 'phone': {
    const d = text.replace(/\D/g, '');
    if (d.length < 9) { reply = 'That doesn\'t look like a full phone number. Please try again.'; break; }
    s.phone = '+' + (d.length === 10 ? '1' + d : d);
    s.step = 'confirm';
    reply = `Please confirm:\n- ${s.service}\n- ${s.slot.label} (${CLINIC.tzLabel})\n- ${s.name}, ${s.phone}\n\nReply YES to book, or NO to start over.`;
    break;
  }
  case 'confirm':
    if (/^(y|yes|confirm|ok|sure)\b/.test(lower)) {
      if (booked.has(s.slot.iso)) { reply = 'Sorry, someone booked that time a moment ago. ' + offerSlots(); break; }
      booking = { sessionId, patient_name: s.name, phone: s.phone, service: s.service, start_iso: s.slot.iso, start_label: s.slot.label, status: 'booked', reminded: false };
      s.step = 'done';
      s.booked = s.slot.label;
      reply = `You're booked! ${s.service} on ${s.slot.label} (${CLINIC.tzLabel}) at ${CLINIC.name}. We'll send a reminder 24 hours before. Reply "new" to book another visit.`;
    } else if (/^(n|no)\b/.test(lower)) {
      s = { step: 'service' };
      reply = 'No problem, let\'s start over. ' + menu();
    } else {
      reply = 'Please reply YES to book, or NO to start over.';
    }
    break;
  case 'done':
    if (lower === 'new') { s = { step: 'service' }; reply = menu(); break; }
    reply = `Your ${s.service} appointment is on ${s.booked}. Reply "new" to book another visit. To cancel or reschedule, please call the clinic.`;
    break;
  default:
    s = { step: 'service' };
    reply = menu();
}

return [{ json: { sessionId, state: JSON.stringify(s), output: reply, booking_created: !!booking, ...(booking || {}) } }];
